function reprString(value) {
  let result = '\'';

  for (const character of value) {
    const codePoint = character.codePointAt(0);

    if (character === '\\') {
      result += '\\\\';
    } else if (character === '\'') {
      result += '\\\'';
    } else if (character === '\n') {
      result += '\\n';
    } else if (character === '\r') {
      result += '\\r';
    } else if (character === '\t') {
      result += '\\t';
    } else if (character === '\b') {
      result += '\\x08';
    } else if (character === '\f') {
      result += '\\x0c';
    } else if (codePoint < 0x20 || codePoint === 0x7f) {
      result += `\\x${codePoint.toString(16).padStart(2, '0')}`;
    } else {
      result += character;
    }
  }

  return `${result}'`;
}

export function pythonRepr(value) {
  if (typeof value === 'string') {
    return reprString(value);
  }

  if (Array.isArray(value)) {
    return `[${value.map((item) => pythonRepr(item)).join(', ')}]`;
  }

  if (value && typeof value === 'object') {
    const entries = Object.keys(value).map((key) => {
      return `${reprString(key)}: ${pythonRepr(value[key])}`;
    });
    return `{${entries.join(', ')}}`;
  }

  if (value === null) {
    return 'None';
  }

  if (value === true) {
    return 'True';
  }

  if (value === false) {
    return 'False';
  }

  return String(value);
}

