const BLOCK_SIZE = 64;

export function hmacSha256(keyBytes, messageBytes) {
  let normalizedKey = keyBytes;

  if (normalizedKey.length > BLOCK_SIZE) {
    normalizedKey = sha256(normalizedKey);
  }

  const keyBlock = new Uint8Array(BLOCK_SIZE);
  keyBlock.set(normalizedKey);

  const inner = new Uint8Array(BLOCK_SIZE + messageBytes.length);
  const outer = new Uint8Array(BLOCK_SIZE + 32);

  for (let index = 0; index < BLOCK_SIZE; index += 1) {
    inner[index] = keyBlock[index] ^ 0x36;
    outer[index] = keyBlock[index] ^ 0x5c;
  }

  inner.set(messageBytes, BLOCK_SIZE);
  outer.set(sha256(inner), BLOCK_SIZE);

  return sha256(outer);
}

