import { hmacSha256 } from '../crypto/hmacSha256.mjs';
import { stringifyJsonAscii } from '../json/asciiJson.mjs';

const encoder = new TextEncoder();
const decoder = new TextDecoder();

function utf8Bytes(text) {
  return encoder.encode(text);
}

function utf8Text(bytes) {
  return decoder.decode(bytes);
}

function timingSafeEqual(left, right) {
  const length = Math.max(left.length, right.length);
  let mismatch = left.length ^ right.length;

  for (let index = 0; index < length; index += 1) {
    const leftCode = index < left.length ? left.charCodeAt(index) : 0;
    const rightCode = index < right.length ? right.charCodeAt(index) : 0;
    mismatch |= leftCode ^ rightCode;
  }

  return mismatch === 0;
}

function signatureFor(signingInput, secret) {
  return encodeBase64Url(hmacSha256(utf8Bytes(secret), utf8Bytes(signingInput)));
}

function parseSegment(segment) {
  return JSON.parse(utf8Text(decodeBase64Url(segment)));
}

export function encode(payload, secret, algorithm = 'HS256') {
  if (algorithm !== 'HS256') {
    throw new Error('Unsupported algorithm');
  }

  const header = { alg: algorithm, typ: 'JWT' };
  const headerSegment = encodeBase64Url(utf8Bytes(stringifyJsonAscii(header)));
  const payloadSegment = encodeBase64Url(utf8Bytes(stringifyJsonAscii(payload)));
  const signingInput = `${headerSegment}.${payloadSegment}`;
  const signatureSegment = signatureFor(signingInput, secret);

  return `${signingInput}.${signatureSegment}`;
}

export function decode(token, secret, options = {}, algorithms = ['HS256']) {
  const parts = token.split('.');

  if (parts.length !== 3) {
    throw new Error('Not enough segments');
  }

  const [headerSegment, payloadSegment, signatureSegment] = parts;
  const header = parseSegment(headerSegment);

  if (!algorithms.includes(header.alg)) {
    throw new Error('The specified alg value is not allowed');
  }

  if (header.alg !== 'HS256') {
    throw new Error('Unsupported algorithm');
  }

