  const expectedSignature = signatureFor(signingInput, secret);

  if (!timingSafeEqual(signatureSegment, expectedSignature)) {
    throw new Error('Signature verification failed');
  }

  const payload = parseSegment(payloadSegment);

  if (options.verify_sub && payload.sub !== undefined && typeof payload.sub !== 'string') {
    throw new Error('Subject must be a string');
  }

  return payload;
}
